-- Run after the expansion DDL inside a transaction and ROLLBACK. Creates no persistent QA accounts.
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();pack uuid;req uuid;room uuid;room2 uuid;r jsonb;v int;hr uuid;gr uuid;
begin
 insert into auth.users(id,email) values(a,'ss-qa-'||a||'@example.invalid'),(b,'ss-qa-'||b||'@example.invalid'),(c,'ss-qa-'||c||'@example.invalid');
 insert into public.ss_profiles(id,username,first_name,last_name,phone,gender) values(a,'qa_a_'||left(a::text,8),'QA','A','09999999001','مرد'),(b,'qa_b_'||left(b::text,8),'QA','B','09999999002','زن'),(c,'qa_c_'||left(c::text,8),'QA','C','09999999003','مرد');
 insert into public.ss_wallets(user_id,balance) values(a,3000),(b,3000),(c,0);
 insert into public.ss_admins(id) values(a);
 insert into public.ss_packages(title,coins,autopilot,auto_shield) values('QA',100,'pro',true) returning id into pack;
 perform public.ss_buy_package(a,pack);
 begin perform public.ss_buy_package(a,pack);raise exception 'QA: duplicate purchase allowed';exception when others then if sqlerrm='QA: duplicate purchase allowed' then raise;end if;end;
 if (select balance from public.ss_wallets where user_id=a)<>2900 then raise exception 'QA: duplicate debit';end if;
 update public.ss_packages set autopilot='none',auto_shield=false where id=pack;
 if public.ss_game_loadout(a)->>'autopilot'<>'pro' or(public.ss_game_loadout(a)->>'auto_shield')::boolean<>true then raise exception 'QA: paid rights changed';end if;
 perform public.ss_hangar(a,'buyDrone','gun');perform public.ss_hangar(a,'equipDrones','',array['gun']);
 begin perform public.ss_hangar(a,'equipDrones','',array['shield']);raise exception 'QA: unequipped unowned drone';exception when others then if sqlerrm='QA: unequipped unowned drone' then raise;end if;end;
 begin perform public.ss_hangar(a,'craft','weapon');raise exception 'QA: free crafting';exception when others then if sqlerrm='QA: free crafting' then raise;end if;end;
 update public.ss_inventory set iron=10,crystal=5,energy=3 where user_id=a;perform public.ss_hangar(a,'craft','weapon');
 if(select weapon_level from public.ss_inventory where user_id=a)<>1 then raise exception 'QA: crafting did not upgrade';end if;
 req:=public.ss_request_friend(a,'qa_b_'||left(b::text,8));
 if exists(select 1 from public.ss_friendships where user_a=least(a,b) and user_b=greatest(a,b)) then raise exception 'QA: friend before consent';end if;
 begin perform public.ss_answer_friend(c,req,true);raise exception 'QA: stranger answered request';exception when others then if sqlerrm='QA: stranger answered request' then raise;end if;end;
 perform public.ss_answer_friend(b,req,false);
 if exists(select 1 from public.ss_friendships where user_a=least(a,b) and user_b=greatest(a,b)) then raise exception 'QA: declined became friends';end if;
 req:=public.ss_request_friend(a,'qa_b_'||left(b::text,8));perform public.ss_answer_friend(b,req,true);
 if not exists(select 1 from public.ss_friendships where user_a=least(a,b) and user_b=greatest(a,b)) then raise exception 'QA: accepted friendship missing';end if;
 begin perform public.ss_invite_coop(a,b,1);raise exception 'QA: offline invite allowed';exception when others then if sqlerrm='QA: offline invite allowed' then raise;end if;end;
 insert into public.ss_presence(user_id) values(a),(b);
 room:=public.ss_invite_coop(a,b,1);
 begin perform public.ss_answer_coop(c,room,true);raise exception 'QA: stranger joined room';exception when others then if sqlerrm='QA: stranger joined room' then raise;end if;end;
 r:=public.ss_answer_coop(b,room,true);hr:=(r->>'host_run')::uuid;gr:=(r->>'guest_run')::uuid;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 if not ss_private.ss_room_access('ss-room:'||room||':'||a,true) or ss_private.ss_room_access('ss-room:'||room||':'||b,true) or not ss_private.ss_room_access('ss-room:'||room||':'||b,false) then raise exception 'QA: broadcast authorization mismatch';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 if ss_private.ss_room_access('ss-room:'||room||':'||a,false) then raise exception 'QA: stranger reads room';end if;
 update public.ss_runs set started_at=now()-interval '20 seconds' where id in(hr,gr);
 r:=public.ss_finish_coop(a,room,'{"won":true,"kills":8,"score":100,"hearts":5,"elapsed":10,"boss_defeated":false,"coins":2,"resources":{"iron":2,"crystal":1,"energy":1}}');
 if r->'host'->>'reward'<>'284' or r->'guest'->>'reward'<>'284' then raise exception 'QA: reward mismatch %',r;end if;
 perform public.ss_finish_coop(a,room,'{}');
 if (select count(*) from public.ss_ledger where user_id=a and reason='first_clear')<>1 then raise exception 'QA: duplicate reward';end if;
 insert into public.ss_runs(user_id,stage,started_at,loadout) values(a,10,now()-interval '20 seconds',public.ss_game_loadout(a)) returning id into hr;
 begin perform public.ss_finish_galaxy(a,hr,9,100,true,5,10,false,'{"iron":0,"crystal":0,"energy":0}',0);raise exception 'QA: boss bypass';exception when others then if sqlerrm='QA: boss bypass' then raise;end if;end;
 r:=public.ss_finish_galaxy(a,hr,9,100,true,5,10,true,'{"iron":0,"crystal":0,"energy":0}',0);
 if r->'resources'->>'crystal'<>'5' then raise exception 'QA: boss material reward missing';end if;
 if r->>'boss_bonus'<>'350' then raise exception 'QA: boss reward missing';end if;
 if public.ss_finish_galaxy(a,hr,9,100,true,5,10,true,'{"iron":0,"crystal":0,"energy":0}',0)<>r then raise exception 'QA: solo retry was not idempotent';end if;
 perform public.ss_support_send(b,'پیام آزمایشی');perform public.ss_support_send(b,'ادامهٔ گفتگو');
 if(select count(*) from public.ss_tickets where user_id=b)<>1 then raise exception 'QA: duplicate chat thread';end if;
 if has_function_privilege('authenticated','public.ss_finish_galaxy(uuid,uuid,integer,integer,boolean,integer,double precision,boolean,jsonb,integer)','execute') then raise exception 'QA: browser may mint rewards';end if;
 raise notice 'Galaxy purchase, crafting, consent, offline guard, private topics, co-op, rewards and chat: passed';
end $$;
